import logging

from typing import Union, List, Optional
from pydantic import ValidationError # type: ignore
from nubra_python_sdk.start_sdk import InitNubraSdk
from nubra_python_sdk.interceptor.htttpclient import BaseHttpClient
from nubra_python_sdk.interceptor.errors import NubraValidationError
from nubra_python_sdk.marketdata.validation import (
    Timeseries,
    MarketChartsResponse,
    OrderBookWrapper,
    OptionChainWrapper,
    CurrentPrice,
    ExchangeEnum,
    MultiStrikeQuery,
    MultiStrikeResponse,
    FundamentalsTypeEnum,
    ResultTypeEnum,
    KeyRatiosResponse,
    CashFlowResponse,
    BalanceSheetResponse,
    ProfitLossResponse,
    CorporateActionsResponse,
    ShareholdingPatternResponse,
    )
logger= logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())
print = lambda *args, **kwargs: None


class MarketData(InitNubraSdk):
    """
    Fetches real-time, historical, and options market data from Nubra.
    """

    def __init__(self, client: InitNubraSdk):
        """
        Initializes the MarketData instance using the provided Nubra SDK client.

        Args:
            client (InitNubraSdk): An authenticated instance of InitNubraSdk.
        """
        self.api_base_url = client.API_BASE_URL
        self.db_path= client.db_path
        self.totp_login = client.totp_login
        self.token_data = client.token_data
        self.db_path = client.db_path
        self.env_path_login = client.env_path_login
        self.client = BaseHttpClient(self)

    def _url(self, path):
        """
        Constructs the full API URL for a given endpoint path.

        Args:
            path (str): Relative API path.

        Returns:
            str: Full API URL.
        """
        return f"{self.api_base_url}/{path}"

    def quote(self, ref_id: int, levels: int):
        """
        Fetches real-time order book data for a given instrument.

        Args:
            ref_id (int): Reference ID of the instrument.
            levels (int): Depth levels of the order book to fetch.

        Returns:
            OrderBookWrapper: Parsed order book data model.

        Raises:
            NubraValidationError: If response fails Pydantic validation.
        """
        ref_id= str(ref_id)
        path = f"orderbooks/{ref_id}"
        if levels:
            levels=f"{levels}"
            path += f"?levels={levels}"
        try:
            response = self.client.request("get", self._url(path))
            if not response:
                return None
            data = response.json()
            if not data:
                return None
            return OrderBookWrapper(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def historical_data(self, request: Union[List[dict], dict]):
        """
        Fetches historical timeseries market data for given instruments and time range.

        This method retrieves OHLCV (Open, High, Low, Close, Volume) or custom field-level 
        data for one or more instruments across a specified date range and interval.

        Args:
            request (Union[List[dict], dict]): 
                A `Timeseries` model, list of models, or equivalent dictionary/dictionaries 
                representing the timeseries query. Each request should include:
                
                - `exchange` (str): Exchange name (e.g., "NSE", "BSE", "MCX"). // enum exchanges
                - `type` (str): Instrument type (e.g., "STOCK", "INDEX").// enum types of data points
                - `values` (List[str]): List of instrument symbols.
                - `fields` (List[str]): Fields to retrieve (e.g., "open", "high", "low", "close", "volume").
                - `startDate` (str): ISO datetime string for start (UTC).
                - `endDate` (str): ISO datetime string for end (UTC).
                - `interval` (str): Interval granularity (e.g., "1d", "5m").// 1d, 1w, 1m, 1h, 1s, 1mth (month), 1y
                - `intraDay` (bool): // if true, then startDate and endDate will be ignored and current date will be picked
                - `realTime` (bool): // TBD

        Returns:
            MarketChartsResponse: A Pydantic model containing structured historical 
            market data, grouped by instrument and field.

        Raises:
            NubraValidationError: If the response JSON is invalid or does not conform to 
            the `MarketChartsResponse` schema.

        Example:
            >>> historical_data({
            ...     "exchange": "NSE",
            ...     "type": "STOCK",
            ...     "values": ["ASIANPAINT", "TATAMOTORS"],
            ...     "fields": ["close", "high", "low", "open", "cumulative_volume"],
            ...     "startDate": "2025-04-19T11:01:57.000Z",
            ...     "endDate": "2025-04-24T06:13:57.000Z",
            ...     "interval": "1d",
            ...     "intraDay": False, 
            ...     "realTime": False
            ... })
        """

        if isinstance(request, dict):
            try:
                request = [Timeseries(**request)]
            except ValidationError as ve:
                return NubraValidationError(ve.errors())
        elif isinstance(request, list) and request and isinstance(request[0], dict):
            try:
                request = [Timeseries(**item) for item in request]
            except ValidationError as ve:
                return {"message": ve.errors()}

        payload = {
            "query": [ts.model_dump(by_alias=True) for ts in request]
        }
        try:
            response = self.client.request("post", self._url("charts/timeseries"), json=payload)
            if not response:
                return None
            data = response.json()
            if not data:
                return None
            return MarketChartsResponse(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def current_price(self, instrument: str, exchange: Optional[ExchangeEnum] = None):
        """
        Fetches the current price data for a specific options instrument.

        Args:
            instrument (str): The symbol of the options instrument (e.g., 'NIFTY', 'BANKNIFTY').

        Returns:
            CurrentPrice: Parsed current option price data.

        Raises:
            NubraValidationError: If response fails Pydantic validation.
        """
        instrument = instrument.upper()
        if exchange == ExchangeEnum.NSE or exchange is None:
            path = f"optionchains/{instrument}/price"
        if exchange == ExchangeEnum.BSE:
            path = f"optionchains/{instrument}/price?exchange=BSE"
        if exchange == ExchangeEnum.MCX:
            path = f"optionchains/{instrument}/price?exchange=MCX"

        try:
            response = self.client.request("get", self._url(path))
            if not response:
                return None
            data = response.json()
            if not data:
                return None
            return CurrentPrice(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def option_chain(self, instrument: str, expiry: Optional[str] = "", exchange: Optional[ExchangeEnum] = None):
        """
        Fetches the full option chain for a given instrument and optional expiry date.

        Args:
            instrument (str): The symbol of the options instrument (e.g., 'NIFTY', 'BANKNIFTY').
            expiry (Optional[str]): Expiry date in 'YYYYMMDD' format. If omitted, latest expiry is used.

        Returns:
            OptionChainWrapper: Parsed option chain data.

        Raises:
            NubraValidationError: If response fails Pydantic validation.

            ValueError: If expiry format is invalid.
        """
        instrument = instrument.upper()
        if exchange == ExchangeEnum.NSE or exchange is None:
            path = f"optionchains/{instrument}"
            if expiry:
                path += f"?expiry={expiry}"

        if exchange == ExchangeEnum.BSE:
            path = f"optionchains/{instrument}?exchange=BSE"
            if expiry:
                path += f"&expiry={expiry}"

        if exchange == ExchangeEnum.MCX:
            path = f"optionchains/{instrument}?exchange=MCX"
            if expiry:
                path += f"&expiry={expiry}"
                
        try:
            response = self.client.request("get", self._url(path))
            if not response:
                return None
            data = response.json()
            if not data:
                return None
            return OptionChainWrapper(**data)
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
    
    def multistrike_data(self, request: Union[List[dict], dict], query_time: Optional[str] = None) -> MultiStrikeResponse:
        """
        Fetches a multi-strike option chain snapshot for one or more assets.

        Sends the queries wrapped under a "query" key to POST /charts/multistrike,
        i.e. the request body is ``{"query": [<MultiStrikeQuery>, ...]}``. For
        chart-specific variants (OI, Volume, etc.) use the dedicated multistrike_*
        methods instead.

        Options mode: provide expiries + strikes/strike range to get per-strike data.
        Futures mode: leave expiries and strikes empty to get FUT data per expiry.

        Args:
            request (Union[List[dict], dict]): One or more MultiStrikeQuery dicts.
                Each dict may include:
                - exchange (str): e.g. "NSE", "BSE"
                - asset (str): e.g. "NIFTY", "BANKNIFTY"
                - expiries (List[str]): expiry strings; empty for futures mode
                - minStrike / maxStrike (int): strike range bounds (ignored when strikes set)
                - strikes (List[int]): explicit strike list (takes precedence over range)
                - fields (List[str]): fields to return (e.g. "close", "iv", "oi", "delta")
                - time (str, optional): snapshot time in "YYYY-MM-DDTHH:MM:SSZ" format (UTC)
            query_time (Optional[str]): Snapshot time applied as the queryTime HTTP header
                across all queries. Per-query time field takes precedence when both are set.
                Format: "YYYY-MM-DDTHH:MM:SSZ" (UTC, no timezone offset).

        Returns:
            MultiStrikeResponse: Nested result keyed by exchange > asset > time > expiry > strike > field.

        Raises:
            NubraValidationError: If request or response validation fails.

        Example:
            >>> multistrike_data([{
            ...     "exchange": "NSE",
            ...     "asset": "NIFTY",
            ...     "expiries": ["2025-05-29"],
            ...     "strikes": [24000, 24500, 25000],
            ...     "fields": ["close", "iv", "oi", "delta"],
            ... }], query_time="2025-05-23T11:30:00Z")
        """
        if isinstance(request, dict):
            try:
                request = [MultiStrikeQuery(**request)]
            except ValidationError as ve:
                raise NubraValidationError(ve.errors())
        elif isinstance(request, list) and request and isinstance(request[0], dict):
            try:
                request = [MultiStrikeQuery(**item) for item in request]
            except ValidationError as ve:
                raise NubraValidationError(ve.errors())
            
        payload = {"query": [q.model_dump(by_alias=True, exclude_none=True) for q in request]}
        headers = {"queryTime": query_time} if query_time else {}
        try:
            response = self.client.request(
                "post",
                self._url("charts/multistrike"),
                json=payload,
                headers=headers,
            )
            return MultiStrikeResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def key_ratios(
        self,
        symbol: str,
        exchange: Optional[ExchangeEnum] = None,
        peers: Optional[str] = None,
        fundamentals_type: Optional[FundamentalsTypeEnum] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
    ) -> KeyRatiosResponse:
        """
        Fetches key ratios, shareholding summary, and technical indicators for a company.

        Args:
            symbol (str): NSE/BSE ticker symbol (e.g. 'INFY').
            exchange (Optional[ExchangeEnum]): NSE or BSE. Defaults to NSE if omitted.
            peers (Optional[str]): Comma-separated peer symbols to include (e.g. 'TCS,WIPRO').
            fundamentals_type (Optional[FundamentalsTypeEnum]): STANDALONE ('S') or CONSOLIDATED ('C').
            limit (Optional[int]): Pagination limit. Omit to use the API default.
            offset (Optional[int]): Pagination offset. Omit to use the API default.

        Returns:
            KeyRatiosResponse: Key ratios, shareholding breakdown, and technical indicators
                for the requested symbol and any peers.

        Raises:
            NubraValidationError: If response fails Pydantic validation.

        Example:
            >>> key_ratios('INFY', exchange=ExchangeEnum.NSE, peers='TCS,WIPRO')
        """
        symbol = symbol.upper()
        params = [f"symbol={symbol}"]
        if exchange:
            params.append(f"exchange={exchange.value}")
        if peers:
            params.append(f"peers={peers}")
        if fundamentals_type:
            params.append(f"type={fundamentals_type.value}")
        if limit is not None:
            params.append(f"limit={limit}")
        if offset is not None:
            params.append(f"offset={offset}")
        path = "screener/fetch_company_fundamentals?" + "&".join(params)
        try:
            response = self.client.request("get", self._url(path))
            return KeyRatiosResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def cash_flow(
        self,
        symbol: str,
        exchange: Optional[ExchangeEnum] = None,
        fundamentals_type: Optional[FundamentalsTypeEnum] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
    ) -> CashFlowResponse:
        """
        Fetches historical cash flow statements for a company.

        Args:
            symbol (str): NSE/BSE ticker symbol.
            exchange (Optional[ExchangeEnum]): NSE or BSE.
            fundamentals_type (Optional[FundamentalsTypeEnum]): STANDALONE or CONSOLIDATED.
            limit (Optional[int]): Number of years to return. Omit to use the API default.
            offset (Optional[int]): Year offset for pagination. Omit to use the API default.

        Returns:
            CashFlowResponse: Operating, investing, and financing cash flows per year.
                Monetary values are plain integers in the vendor's scaled unit (int64);
                ratio rows (`is_key_ratio=True`) are plain floats. Values may be null.

        Raises:
            NubraValidationError: If response fails Pydantic validation.

        Example:
            >>> cash_flow('INFY', exchange=ExchangeEnum.NSE,
            ...           fundamentals_type=FundamentalsTypeEnum.CONSOLIDATED, limit=5)
        """
        symbol = symbol.upper()
        params = [f"symbol={symbol}"]
        if exchange:
            params.append(f"exchange={exchange.value}")
        if fundamentals_type:
            params.append(f"type={fundamentals_type.value}")
        if limit is not None:
            params.append(f"limit={limit}")
        if offset is not None:
            params.append(f"offset={offset}")
        path = "screener/fetch_company_fundamentals/cash_flow?" + "&".join(params)
        try:
            response = self.client.request("get", self._url(path))
            return CashFlowResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

