    def profit_loss(
        self,
        symbol: str,
        exchange: Optional[ExchangeEnum] = None,
        fundamentals_type: Optional[FundamentalsTypeEnum] = None,
        result_type: Optional[ResultTypeEnum] = None,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
    ) -> ProfitLossResponse:
        """
        Fetches historical profit and loss statements for a company.

        Args:
            symbol (str): NSE/BSE ticker symbol.
            exchange (Optional[ExchangeEnum]): NSE or BSE.
            fundamentals_type (Optional[FundamentalsTypeEnum]): STANDALONE or CONSOLIDATED.
            result_type (Optional[ResultTypeEnum]): ANNUAL ('A') or QUARTERLY ('Q').
                Quarterly dates use format '2024Q1'–'2024Q4'.
            limit (Optional[int]): Number of periods to return. Omit to use the API default.
            offset (Optional[int]): Period offset for pagination. Omit to use the API default.

        Returns:
            ProfitLossResponse: Income, expenses, and profit rows per period.
                Rows with `is_key_ratio=True` contain plain float values (margins, NPA %)
                rather than scaled integers.

        Raises:
            NubraValidationError: If response fails Pydantic validation.

        Example:
            >>> profit_loss('RELIANCE', exchange=ExchangeEnum.NSE,
            ...             result_type=ResultTypeEnum.QUARTERLY, limit=8)
        """
        symbol = symbol.upper()
        params = [f"symbol={symbol}"]
        if exchange:
            params.append(f"exchange={exchange.value}")
        if fundamentals_type:
            params.append(f"type={fundamentals_type.value}")
        if result_type:
            params.append(f"result_type={result_type.value}")
        if limit is not None:
            params.append(f"limit={limit}")
        if offset is not None:
            params.append(f"offset={offset}")
        path = "screener/fetch_company_fundamentals/profit_loss?" + "&".join(params)
        try:
            response = self.client.request("get", self._url(path))
            return ProfitLossResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def corp_actions(
        self,
        symbol: str,
        exchange: Optional[ExchangeEnum] = None,
    ) -> CorporateActionsResponse:
        """
        Fetches recent and upcoming corporate actions for a company.

        Includes dividends, bonuses, splits, rights issues, buybacks, mergers, and demergers.

        Args:
            symbol (str): NSE/BSE ticker symbol (e.g. 'TCS').
            exchange (Optional[ExchangeEnum]): NSE or BSE. Defaults to NSE if omitted.

        Returns:
            CorporateActionsResponse: List of corporate action records.
                `upcoming_event=True` means the event has not yet occurred.
                Ratio fields `ratio1`/`ratio2` encode bonus/split ratios (e.g. 1:2 bonus → ratio1=1, ratio2=2).

        Raises:
            NubraValidationError: If response fails Pydantic validation.

        Example:
            >>> corp_actions('TCS', exchange=ExchangeEnum.NSE)
        """
        symbol = symbol.upper()
        params = [f"symbol={symbol}"]
        if exchange:
            params.append(f"exchange={exchange.value}")
        path = "screener/fetch_company_fundamentals/corp_actions?" + "&".join(params)
        try:
            response = self.client.request("get", self._url(path))
            return CorporateActionsResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())

    def shareholding_pattern(
        self,
        fincode: int,
        limit: Optional[int] = None,
        offset: Optional[int] = None,
    ) -> ShareholdingPatternResponse:
        """
        Fetches historical quarterly shareholding breakdowns for a company.

        Provides promoter, institutional, and retail holding percentages down to
        individual entity level. Requires `fincode`, not a ticker symbol — obtain it
        from `key_ratios()` response: `result.keyratios_shareholding.fincode`.

        Args:
            fincode (int): Internal financial code for the company.
            limit (Optional[int]): Number of quarters to return. Omit to use the API default.
            offset (Optional[int]): Quarter offset for pagination. Omit to use the API default.

        Returns:
            ShareholdingPatternResponse: Quarterly shareholding rows.
                Top-level breakdown is in `shareholding_children`; deeper levels use `children`.
                All values are percentages (e.g. 14.9 means 14.9%).

        Raises:
            NubraValidationError: If response fails Pydantic validation.

        Example:
            >>> # First get fincode
            >>> kr = key_ratios('INFY', exchange=ExchangeEnum.NSE)
            >>> fincode = kr.result.keyratios_shareholding.fincode
            >>> shareholding_pattern(fincode, limit=4)
        """
        params = [f"fincode={fincode}"]
        if limit is not None:
            params.append(f"limit={limit}")
        if offset is not None:
            params.append(f"offset={offset}")
        path = "screener/fetch_company_fundamentals/shareholding_pattern?" + "&".join(params)
        try:
            response = self.client.request("get", self._url(path))
            return ShareholdingPatternResponse(**response.json())
        except ValidationError as ve:
            raise NubraValidationError(ve.errors())
 
